const films=[{title:'The Last Light',genre:'DRAMA · 104 MIN',times:['18:30','21:00'],tonight:true,desc:'A quiet journey through a city after the lights go out. A fictional tale about the places and people we carry with us.'},{title:'Velvet Hours',genre:'ROMANCE · 96 MIN',times:['19:15'],tonight:true,desc:'Two strangers meet in the hours between the last train and the first morning light.'},{title:'Blue Static',genre:'MYSTERY · 111 MIN',times:['20:45'],tonight:false,desc:'A late-night radio signal draws a sound engineer into a mystery hidden in plain sight.'},{title:'Somewhere, Slowly',genre:'DOCUMENTARY · 88 MIN',times:['17:00'],tonight:false,desc:'A fictional meditation on the small rituals that make unfamiliar places feel like home.'}];const list=document.querySelector('#films');function render(filter='all'){let shown=films.filter(f=>filter!=='tonight'||f.tonight);list.innerHTML=shown.map(f=>`<article class="film-row"><span class="film-index">${String(films.indexOf(f)+1).padStart(2,'0')}</span><div class="film-title">${f.title}<small>${f.genre}</small></div><div class="film-times">${f.times.map(t=>`<span>${t}</span>`).join('')}</div><button data-film="${films.indexOf(f)}">DETAILS</button></article>`).join('')}document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b?'true':'false')});render(b.dataset.filter)}));const dialog=document.querySelector('#details');list.addEventListener('click',e=>{const button=e.target.closest('[data-film]');if(!button)return;const film=films[button.dataset.film];document.querySelector('#dialogTitle').textContent=film.title;document.querySelector('#dialogGenre').textContent=film.genre;document.querySelector('#dialogDesc').textContent=film.desc;document.querySelector('#dialogMeta').textContent='SCREENING TIMES  '+film.times.join('  /  ');dialog.showModal()});document.querySelector('#close').onclick=()=>dialog.close();document.querySelector('#done').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});render();
